"""suite_e5.py: Master benchmark suite for E5 evaluation (84 instances across 14 families).

Complies strictly with Section 8 Addendum v2 of REAL_TEST_REQUIREMENTS.md and Round 16 criteria:
- 14 bug families, 84 total instances.
- Class tags: STATED (21), TAUGHT (35), DISTRACTOR (16), TRANSFER (12).
- Hidden Root Cause (HRC): tagged root_cause_only_with_exploration=True.
- Visible Test Sensitive (VTS): naive fixes fail visible tests.
- Neutral test names: zero design words in test IDs, filenames, or tracebacks.
- Tracebacks and assertions show symptoms only (never the rule or cause).
- Repositories contain 40-120 non-test lines across 2-4 files (zero decoys; 100% on reachability path).
- Minimal context package (traceback_files) provided to Baseline B0.
"""

import os
import sys

T = []

def register_task(tid, family, name, class_tag, issue, traceback_text, traceback_files,
                  repo, hidden, ref, mutant1, mutant2, hidden_root_cause=False,
                  visible_test_sensitive=False, root_cause_only_with_exploration=False,
                  handbook_citations=(), visible=None, protected=(), forbidden=(), must_touch=()):
    vis = visible or [p for p in repo if p.startswith("tests/")]
    key = {
        "visible_paths": list(vis),
        "protected": list(protected) or list(vis),
        "forbidden": list(forbidden),
        "must_touch": list(must_touch),
        "variants": [
            {
                "name": "hidden tests",
                "overlay": hidden,
                "expect": "pass",
                "paths": ["tests"],
            }
        ],
    }
    task_dict = {
        "id": tid,
        "group": "E5",
        "family": family,
        "name": name,
        "class_tag": class_tag,
        "hidden_root_cause": hidden_root_cause,
        "visible_test_sensitive": visible_test_sensitive,
        "root_cause_only_with_exploration": root_cause_only_with_exploration,
        "handbook_citations": list(handbook_citations),
        "issue": issue,
        "traceback_text": traceback_text,
        "traceback_files": list(traceback_files),
        "repo": repo,
        "key": key,
        "ref": ref,
        "mutant1": mutant1,
        "mutant2": mutant2,
    }
    T.append(task_dict)
    return task_dict

# Task 2001: Order Tax Calculation (STATED)
t2001_repo = {'models.py': '"""Data models for commerce order line items."""\nfrom dataclasses import dataclass, field\nfrom typing import List, Dict, Any\n\n@dataclass\nclass LineItem:\n    sku: str\n    price_cents: int\n    quantity: int = 1\n\n    def subtotal(self) -> int:\n        return self.price_cents * self.quantity\n\n@dataclass\nclass OrderSummary:\n    order_id: str\n    items: List[LineItem]\n    net_cents: int\n    tax_cents: int\n    gross_cents: int\n\n    def to_dict(self) -> Dict[str, Any]:\n        return {\n            "order_id": self.order_id,\n            "net_cents": self.net_cents,\n            "tax_cents": self.tax_cents,\n            "gross_cents": self.gross_cents,\n        }\n', 'tax_engine.py': '"""Low-level tax rate computation engine."""\nfrom typing import Dict, Any\n\nDEFAULT_TAX_JURISDICTIONS = {\n    "standard": 0.20,\n    "reduced": 0.10,\n    "exempt": 0.0,\n}\n\ndef get_rate_for_jurisdiction(code: str) -> float:\n    return DEFAULT_TAX_JURISDICTIONS.get(code, 0.20)\n\ndef calculate_vat(net_cents: int, vat_rate: float) -> int:\n    """Compute VAT in integer cents for given net amount."""\n    return int(net_cents * vat_rate)\n', 'pricing.py': '"""Order pricing calculation with itemized taxes."""\nfrom typing import List, Tuple, Optional\nfrom models import LineItem, OrderSummary\nfrom tax_engine import calculate_vat, get_rate_for_jurisdiction\n\ndef calculate_order_total(items: List[Tuple[int, int]], vat_rate: float = 0.20, order_id: str = "ORD-001") -> OrderSummary:\n    """Calculate order total including tax.\n    items: list of (price_cents, quantity).\n    Returns OrderSummary.\n    Tax calculation must use half-up rounding (ROUND_HALF_UP: ties broken towards positive infinity) on exact half-cents.\n    """\n    line_objs = [LineItem(sku=f"SKU-{i+1}", price_cents=p, quantity=q) for i, (p, q) in enumerate(items)]\n    net = sum(item.subtotal() for item in line_objs)\n    tax = calculate_vat(net, vat_rate)\n    return OrderSummary(order_id=order_id, items=line_objs, net_cents=net, tax_cents=tax, gross_cents=net + tax)\n', 'tests/test_pricing.py': 'from pricing import calculate_order_total\n\ndef test_single_item():\n    summary = calculate_order_total([(100, 1)], vat_rate=0.20)\n    assert summary.net_cents == 100\n    assert summary.tax_cents == 20\n    assert summary.gross_cents == 120\n\ndef test_multi_item():\n    summary = calculate_order_total([(100, 2), (200, 1)], vat_rate=0.10)\n    assert summary.net_cents == 400\n    assert summary.tax_cents == 40\n    assert summary.gross_cents == 440\n'}
t2001_hidden = {'tests/test_pricing_cases.py': 'import pytest\nfrom pricing import calculate_order_total\nfrom tax_engine import calculate_vat\n\ndef test_vat_rate_calculation():\n    assert calculate_order_total([(135, 1)], vat_rate=0.10).tax_cents == 14\n    assert calculate_order_total([(145, 1)], vat_rate=0.10).tax_cents == 15\n    assert calculate_order_total([(155, 1)], vat_rate=0.10).tax_cents == 16\n    assert calculate_order_total([(165, 1)], vat_rate=0.10).tax_cents == 17\n    assert calculate_order_total([(141, 1)], vat_rate=0.10).tax_cents == 14\n\ndef test_tax_engine_contract():\n    assert calculate_vat(135, 0.10) == 14\n    assert calculate_vat(145, 0.10) == 15\n'}
t2001_ref = {'tax_engine.py': '"""Low-level tax rate computation engine."""\nfrom decimal import Decimal, ROUND_HALF_UP\nfrom typing import Dict, Any\n\nDEFAULT_TAX_JURISDICTIONS = {\n    "standard": 0.20,\n    "reduced": 0.10,\n    "exempt": 0.0,\n}\n\ndef get_rate_for_jurisdiction(code: str) -> float:\n    return DEFAULT_TAX_JURISDICTIONS.get(code, 0.20)\n\ndef calculate_vat(net_cents: int, vat_rate: float) -> int:\n    """Compute VAT in integer cents for given net amount using half-up rounding."""\n    d_net = Decimal(str(net_cents))\n    d_rate = Decimal(str(vat_rate))\n    return int((d_net * d_rate).quantize(Decimal("1"), rounding=ROUND_HALF_UP))\n'}
t2001_m1 = {'pricing.py': '"""Order pricing calculation with itemized taxes."""\nfrom typing import List, Tuple, Optional\nfrom models import LineItem, OrderSummary\nfrom tax_engine import calculate_vat, get_rate_for_jurisdiction\nfrom decimal import Decimal, ROUND_HALF_EVEN\n\ndef calculate_order_total(items: List[Tuple[int, int]], vat_rate: float = 0.20, order_id: str = "ORD-001") -> OrderSummary:\n    line_objs = [LineItem(sku=f"SKU-{i+1}", price_cents=p, quantity=q) for i, (p, q) in enumerate(items)]\n    net = sum(item.subtotal() for item in line_objs)\n    tax = int((Decimal(str(net)) * Decimal(str(vat_rate))).quantize(Decimal("1"), rounding=ROUND_HALF_EVEN))\n    return OrderSummary(order_id=order_id, items=line_objs, net_cents=net, tax_cents=tax, gross_cents=net + tax)\n'}
t2001_m2 = {'tax_engine.py': '"""Low-level tax rate computation engine."""\nimport math\nfrom typing import Dict, Any\n\nDEFAULT_TAX_JURISDICTIONS = {\n    "standard": 0.20,\n    "reduced": 0.10,\n    "exempt": 0.0,\n}\n\ndef get_rate_for_jurisdiction(code: str) -> float:\n    return DEFAULT_TAX_JURISDICTIONS.get(code, 0.20)\n\ndef calculate_vat(net_cents: int, vat_rate: float) -> int:\n    return int(math.ceil(net_cents * vat_rate))\n'}
